/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// Refactor
/// </summary>
abstract class METTAMRebateQueryBuilderORAttributes
{
    Query           query;
    TAMRebateTable  rebateTable;
    TAMRebateQueryBuilder rebateQueryBuilder;

    str andQueryRanges, orQueryRanges;

    QueryBuildDataSource qbds;

    boolean queryRangesAdded;

    GUPRefRecId pricingRuleRefRecId;
    FieldId rangeFieldId;

}

Method.Source:
/// <summary>
/// Construct a new instance of METTAMRebateQueryBuilderORAttributes
/// </summary>
/// <param name = "_headerLines"><c>HeaderLines_IT</c></param>
/// <param name = "_rebateQueryBuilder"><c>TAMRebateQueryBuilder</c></param>
/// <param name = "_rebateTable"><c>TAMRebateTable</c></param>
/// <param name = "_query"><c>Query</c></param>
/// <returns><c>METTAMRebateQueryBuilderORAttributes</c></returns>
public static METTAMRebateQueryBuilderORAttributes construct(HeaderLines_IT _headerLines, TAMRebateQueryBuilder _rebateQueryBuilder, TAMRebateTable _rebateTable, Query _query)
{
    METRebateOrAttribute attribute = new METRebateOrAttribute(_headerLines, false);

    METTAMRebateQueryBuilderORAttributes ret = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(METTAMRebateQueryBuilderORAttributes), attribute) as METTAMRebateQueryBuilderORAttributes;

    if (!ret)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    ret.rebateQueryBuilder = _rebateQueryBuilder;
    ret.query = _query;
    ret.rebateTable = _rebateTable;
    ret.init();

    return ret;
}

/// <summary>
/// Bug 332315: CB201- "Preview customers" for OR attribute functionality
/// Construct a new instance of METTAMRebateQueryBuilderORAttributes
/// </summary>
/// <param name = "_headerLines"><c>HeaderLines_IT</c></param>
/// <param name = "_rebateQueryBuilder"><c>TAMRebateQueryBuilder</c></param>
/// <param name = "_rebateTable"><c>TAMRebateTable</c></param>
/// <param name = "_query"><c>Query</c></param>
/// <returns><c>METTAMRebateQueryBuilderORAttributes</c></returns>
public static METTAMRebateQueryBuilderORAttributes constructPreview(HeaderLines_IT _headerLines, Query _query, GUPRefRecId _pricingRuleCopyRefRecId)
{
    METRebateOrAttribute attribute = new METRebateOrAttribute(_headerLines, true);

    METTAMRebateQueryBuilderORAttributes ret = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(METTAMRebateQueryBuilderORAttributes), attribute) as METTAMRebateQueryBuilderORAttributes;

    if (!ret)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    ret.query = _query;
    ret.init();

    ret.pricingRuleRefRecId = _pricingRuleCopyRefRecId;

    return ret;
}

/// <summary>
/// Check if query ranges have been added with OR attributes
/// </summary>
/// <returns>True if query ranges have been added; otherwise, false</returns>
public boolean hasQueryRangesAdded()
{
    return queryRangesAdded;
}

/// <summary>
/// Run the OR attributes filtering logic
/// </summary>
/// <returns>Updated <c>Query</c> object</returns>
public Query run()
{               
    // Run for attributes
    queryRangesAdded = this.processPricingRule();  

    return query;    
}

/// <summary>
/// Bug 332315: CB201- "Preview customers" for OR attribute functionality
/// Only check those rules which have OR conditions here.
/// For those rules without OR conditions, the original query building logic can handle them.
/// </summary>
/// <returns>GUPPricingRuleCondition.RecId where OR conditions exists; otherwise, false</returns>
RecId isPricingRuleWithORConditionExists()
{
    GUPPricingRule pricingRule;
    GUPPricingRuleCondition ruleCondition;

    select firstonly RecId from pricingRule
            where pricingRule.RecId == pricingRuleRefRecId
               && pricingRule.PriceAttributeGroupName != ''
            exists join ruleCondition
            where ruleCondition.RuleId == pricingRule.RecId
               && ruleCondition.METisOR == NoYes::Yes;
    return pricingRule.RecId;
}

/// <summary>
/// Process pricing rule with OR conditions
/// </summary>
/// <returns>True if query ranges have been added; otherwise, false</returns>
protected boolean processPricingRule()
{
    GUPPricingRule pricingRule;
    GUPPricingRuleCondition ruleCondition;

    boolean queryRangesAddedLocal = false;

    RecId pricingRuleRecId = this.isPricingRuleWithORConditionExists();

    // Build query ranges for header rule with OR conditions
    if (pricingRuleRecId)
    {
        // Process rule conditions
        this.processRuleConditions(pricingRuleRecId);

        // And the end the condition is ((AndAttr1 && AndAttr2 && ...) && (OrAttr1 || OrAttr2 || ...))
        str queryRanges;
        if (andQueryRanges)
        {
            queryRanges += '(' + andQueryRanges + ')' + (orQueryRanges != '' ? (' && ' + '(' + orQueryRanges + ')') : '');
        }
        else
        {
            queryRanges = orQueryRanges;
        }

        if (queryRanges)
        {
            // For dubug
            // info("Line Rule Query Ranges: " + queryRanges);
            queryRangesAddedLocal = true;                
            QueryBuildRange qbr = qbds.addRange(rangeFieldId);
            qbr.value(queryRanges);
            qbr.status(RangeStatus::Hidden);
        }
    }

    return queryRangesAddedLocal;
}

