/// <summary>
/// Bug 332315: CB201- "Preview customers" for OR attribute functionality
/// Refactoring for preview customers
/// </summary>
/// <param name = "_ruleIdRecId"></param>
/// <returns><c>Query</c></returns>
protected Query buildRuleConditionQuery(GUPRefRecId _ruleIdRecId)
{
    Query ruleConditionQuery = new Query();
    QueryBuildDataSource ruleConditionQbds = ruleConditionQuery.addDataSource(this.tablenumPricingRuleCondition());
    ruleConditionQbds.addRange(this.fieldNumRuleId()).value(queryValue(_ruleIdRecId));
    ruleConditionQbds.addRange(this.fieldNumConditionValue()).value(SysQuery::valueNotEmptyString());

    QueryBuildDataSource attributeLinkQbds = ruleConditionQbds.addDataSource(tableNum(GUPPricingAttributeLink));
    attributeLinkQbds.joinMode(JoinMode::InnerJoin);
    attributeLinkQbds.addLink(this.fieldNumConditionAttribute(), fieldNum(GUPPricingAttributeLink, RecId));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, AttributeName));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, TypeName));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, RecId));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, PriceAttributeClassId));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, Source));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, AttributeProviderClassId));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, SourceName));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, FieldName));
    attributeLinkQbds.addSelectionField(fieldNum(GUPPricingAttributeLink, AttributeDataType));

    return ruleConditionQuery;
}

/// <summary>
/// Bug 332315: CB201- "Preview customers" for OR attribute functionality
/// Refactoring for preview customers
/// </summary>
/// <param name = "_qr"><c>QueryRun</c></param>
/// <returns><c>GUPPricingRuleCondition</c></returns>
GUPPricingRuleCondition getRuleConditionFromQueryRun(QueryRun _qr)
{
    return _qr.get(tableNum(GUPPricingRuleCondition));
}

/// <summary>
/// Process rule conditions
/// </summary>
/// <param name = "_refRecId">Pricing rule ref rec id</param>
protected void processRuleConditions(GUPRefRecId _refRecId)
{
    GUPPricingRuleCondition ruleCondition;
    GUPPricingAttributeLink attributeLink;        

    boolean isOrConditionSetToALL = false;

    // Build ruleCondition query
    Query ruleConditionQuery = this.buildRuleConditionQuery(_refRecId);

    QueryRun qr = new QueryRun(ruleConditionQuery);

    // Loop through all attribute conditions
    while (qr.next())
    {
        // Get ruleCondition
        ruleCondition = this.getRuleConditionFromQueryRun(qr);
        attributeLink = qr.get(tableNum(GUPPricingAttributeLink));

        // Get qbdsName
        str qbdsName = this.getQbdsName(attributeLink);

        if (!qbdsName)
        {
            continue;
        }

        // If OR condition is already set to ALL, then skip all other OR conditions.
        if (ruleCondition.METisOR == NoYes::Yes && isOrConditionSetToALL)
        {
            continue;
        }

        // If one Or condition is set with empty value(ALL), that means no matter what is the setting on transaction, all OR conditions are matched.
        if (ruleCondition.METisOR == NoYes::Yes && ruleCondition.ConditionValue == '')
        {
            isOrConditionSetToALL = true;
            orQueryRanges = '';
            continue;
        }

        // Skip the AND condition with empty value.
        if (ruleCondition.METisOR == NoYes::No && ruleCondition.ConditionValue == '')
        {
            continue;
        }

        // All AND conditions are combined with && in query script
        if (ruleCondition.METisOR == NoYes::No && andQueryRanges)
        {
            andQueryRanges  += ' && ';
        }

        // All OR conditions are combined with || in query script
        if (ruleCondition.METisOR == NoYes::Yes && orQueryRanges)
        {
            orQueryRanges  += ' || ';
        }

        // handle inclusion/exclusion
        this.buildSingleQueryRange(ruleCondition, attributeLink, qbdsName);
    }
}

/// <summary>
/// Get the name of the query build data source (qbds) for the given attribute link
/// </summary>
/// <param name = "_attributeLink">The attribute link object</param>
/// <returns>The name of the qbds as a string</returns>
abstract protected str getQbdsName(GUPPricingAttributeLink _attributeLink)
{

}

/// <summary>
/// Build a single query range based on the given rule condition, attribute link, and qbds name
/// </summary>
/// <param name = "_ruleCondition">The rule condition object</param>
/// <param name = "_attributeLink">The attribute link object</param>
/// <param name = "_qbdsName">The name of the query build data source</param>
protected void buildSingleQueryRange(GUPPricingRuleCondition _ruleCondition, GUPPricingAttributeLink _attributeLink, str _qbdsName)
{
    str singleQueryRange;

    singleQueryRange = this.processRuleConditionValue(_ruleCondition, _attributeLink, _qbdsName);

    if (_ruleCondition.METisOR == NoYes::No)
    {
        andQueryRanges += '(' + singleQueryRange + ')';
    }

    if (_ruleCondition.METisOR == NoYes::Yes)
    {
        orQueryRanges += '(' + singleQueryRange + ')';
    }
}

/// <summary>
/// Process the value of a rule condition to generate a query range string
/// </summary>
/// <param name = "_ruleCondition">The rule condition object</param>
/// <param name = "_attributeLink">The attribute link object</param>
/// <param name = "_qbdsName">The name of the query build data source</param>
/// <returns>A string representing the query range</returns>
protected str processRuleConditionValue(GUPPricingRuleCondition _ruleCondition, GUPPricingAttributeLink _attributeLink, str _qbdsName)
{
    str value;
    str singleQueryRange;

    // For text data type, need to add double quote for the value in query range.
    // For int, reference data type, no need to add double quote for the value in query range.
    // For trueFalse data type, use 1 (in price rule condition, it is 'Yes') for true and 0 for false without double quote.
    // Need to add logic for trueFalse data type, I didn't cover the case in this examaple.
    str queryFmt = _attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '%1.%2 %3 "%4"' : '%1.%2 %3 %4';

    // If the condition value contains '!', that means it is a NOT EQUAL condition. Translate it to ((X.Y != Value1) && (X.Y!= Value2) && ...)                    
    boolean isExclusion = strContains(_ruleCondition.ConditionValue, '!');
    str operatorStr = isExclusion ? '!=' : '==';

    // Multiple values comma separated
    if (strContains(_ruleCondition.ConditionValue, ','))
    {
        List list = isExclusion ?
            strSplit(strReplace(_ruleCondition.ConditionValue, '!', ''), ',') :
            strSplit(_ruleCondition.ConditionValue, ',');

        ListEnumerator valuesListEnumerator = list.getEnumerator();

        while (valuesListEnumerator.moveNext())
        {
            if (singleQueryRange)
            {
                singleQueryRange += isExclusion ? ' && ' : ' || ';
            }

            // for customer and product attributes, need to add extra condition on the attribute name
            if (_attributeLink.AttributeName == METConstants::Brand
            ||  _attributeLink.AttributeName == METConstants::PrivateLabel
            ||  _attributeLink.AttributeName == METConstants::CustomerSuperGroup
            ||  _attributeLink.AttributeName == METConstants::BannerGroup)
            {
                queryFmt = _attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 %3 "%4") && (%1.%5 == "%6")' : '(%1.%2 %3 %4) && (%1.%5 == "%6")';

                value = valuesListEnumerator.current();

                // ConditionValue is saved as a string 'Yes'/'No' for boolean attribute 'Private label'
                // Need to convert it to 1/0 for the query range
                if (_attributeLink.AttributeName == METConstants::PrivateLabel)
                {
                    value = value == 'Yes' ? '1' : '0';
                }

                singleQueryRange += strFmt('(' + queryFmt + ')',
                                            _qbdsName,
                                            METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(_attributeLink),
                                            operatorStr,
                                            value,
                                            fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                            _attributeLink.AttributeName);

            }
            else
            {
                // MS code
                singleQueryRange += strFmt('(' + queryFmt + ')', _qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(_attributeLink), operatorStr, valuesListEnumerator.current());
            }
        }
    }
    // Single value
    else // EQUAL condition . Translate it to ((X.Y == Value1) || (X.Y == Value2) || ...)
    {
        value = isExclusion ?
                strReplace(_ruleCondition.ConditionValue, '!', '') :
                _ruleCondition.ConditionValue;

        // for customer and product attributes, need to add extra condition on the attribute name
        if (_attributeLink.AttributeName == METConstants::Brand
        ||  _attributeLink.AttributeName == METConstants::PrivateLabel
        ||  _attributeLink.AttributeName == METConstants::CustomerSuperGroup
        ||  _attributeLink.AttributeName == METConstants::BannerGroup)
        {                
            queryFmt = _attributeLink.AttributeDataType == enum2Str(AttributeDataType::Text) ? '(%1.%2 %3 "%4") && (%1.%5 == "%6")' : '(%1.%2 %3 %4) && (%1.%5 == "%6")';                

            // ConditionValue is saved as a string 'Yes'/'No' for boolean attribute 'Private label'
            // Need to convert it to 1/0 for the query range
            if (_attributeLink.AttributeName == METConstants::PrivateLabel)
            {
                value = _ruleCondition.ConditionValue == 'Yes' ? '1' : '0';
            }

            singleQueryRange = strFmt(queryFmt,
                                            _qbdsName,
                                            METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(_attributeLink),
                                            operatorStr,
                                            value,
                                            fieldStr(GUPEcoResInstanceAttributeValuesView, AttributeName),
                                            _attributeLink.AttributeName);
        }
        else
        {
            // MS code
            singleQueryRange = strFmt(queryFmt, _qbdsName, METGUPRebateQueryBuilderHelper::getFieldStrFromAttributeLink(_attributeLink), operatorStr, value);
        }
    }

    return singleQueryRange;
}
